mapper.select:
select 
from basket_tournament t
where t.is_delete = 0
and t.tournament_no like concat('%', #{tournamentNo}, '%')
and t.tournament_name like concat('%', #{tournamentName}, '%')
and t.tournament_status = #{tournamentStatus}
and t.competition_season_id = #{competitionSeasonId}

    and (t.registration_start_time is null or t.registration_end_time is null)


    and t.registration_start_time is not null and t.registration_end_time is not null
    and now() < t.registration_start_time


    and t.registration_start_time is not null and t.registration_end_time is not null
    and now() >= t.registration_start_time and now() <= t.registration_end_time


    and t.registration_start_time is not null and t.registration_end_time is not null
    and now() > t.registration_end_time


    and t.registration_end_time >= #{registrationTimeBegin}


    and t.registration_start_time <= #{registrationTimeEnd}


    and t.competition_end_time >= #{competitionTimeBegin}


    and t.competition_start_time <= #{competitionTimeEnd}

order by t.display_order, t.create_time desc

